import { Component, OnInit } from '@angular/core';
import { FormBuilder, FormGroup, Validators } from '@angular/forms';
import { ActivatedRoute, Router } from '@angular/router';
import { MessageService } from 'primeng/api';
import { AdminMenusService } from '../../../../../../libs/openapi/src/api/admin-menus.service';
import { MenuInput } from '../../../../../../libs/openapi/src/model/menu-input';
import { MenuCreationOptions } from '../../../../../../libs/openapi/src/model/menu-creation-options';
import { Menu } from '../../../../../../libs/openapi/src/model/menu';
import { MenuCreationOptionsMenuTypesInner } from '../../../../../../libs/openapi/src/model/menu-creation-options-menu-types-inner';
import { Category, CategoryService } from '../../../../../../libs/openapi/src';

@Component({
  selector: 'app-menu-form',
  templateUrl: './menu-form.component.html',
  styleUrls: ['./menu-form.component.scss'],
  providers: [MessageService],
})
export class MenuFormComponent implements OnInit {
  menuForm: FormGroup;
  isEditMode = false;
  menuId: string | null = null;
  loading = false;
  submitting = false;
  menuOptions: MenuCreationOptions | null = null;

  menuTypes: MenuCreationOptionsMenuTypesInner[] = [];
  singlePageOptions: MenuCreationOptionsMenuTypesInner[] = [];
  categoryOptions: Category[] = [];

  requiredRoles = [
    { label: '公開', value: 'public' },
    { label: '會員', value: 'member' },
    { label: '管理員', value: 'admin' },
  ];

  contentTypes = [
    { label: '產品', value: 'product' },
    { label: '文章', value: 'article' },
    { label: '頁面', value: 'page' },
  ];

  displayStyles = [
    { label: '網格', value: 'grid' },
    { label: '列表', value: 'list' },
    { label: '卡片', value: 'card' },
  ];

  sortByOptions = [
    { label: '建立時間', value: 'createdAt' },
    { label: '更新時間', value: 'updatedAt' },
    { label: '名稱', value: 'name' },
    { label: '排序', value: 'displayOrder' },
  ];

  sortOrderOptions = [
    { label: '升序', value: 'asc' },
    { label: '降序', value: 'desc' },
  ];

  constructor(
    private formBuilder: FormBuilder,
    private adminMenusService: AdminMenusService,
    private categoryService: CategoryService,
    private messageService: MessageService,
    private router: Router,
    private route: ActivatedRoute
  ) {
    this.menuForm = this.createForm();
  }

  ngOnInit() {
    this.menuId = this.route.snapshot.paramMap.get('id');
    this.isEditMode = !!this.menuId;

    this.loadMenuOptions();
    this.loadCategoryOptions();
    if (this.isEditMode) {
      this.loadMenuForEdit();
    }

    // 監聽選單類型變化
    this.menuForm.get('menuType')?.valueChanges.subscribe((value) => {
      this.onMenuTypeChange(value);
    });
  }

  private createForm(): FormGroup {
    return this.formBuilder.group({
      name: ['', [Validators.required, Validators.maxLength(100)]],
      slug: [''],
      menuType: ['', Validators.required],
      displayOrder: [1, [Validators.min(1), Validators.max(999)]],
      isActive: [true],
      parentId: [''],
      level: [1, [Validators.min(1), Validators.max(3)]],
      requiredRole: ['public'],
      icon: [''],
      description: ['', Validators.maxLength(500)],

      // Category config
      categoryConfig: this.formBuilder.group({
        contentType: ['product'],
        displayStyle: ['grid'],
        itemsPerPage: [12, [Validators.min(1), Validators.max(100)]],
        sortBy: ['createdAt'],
        sortOrder: ['desc'],
        categoryFilter: [''],
        tagFilter: [[]],
        enableSearch: [true],
        enableCategoryFilter: [true],
      }),

      // Single config
      singleConfig: this.formBuilder.group({
        contentId: [''],
        openInNewTab: [false],
      }),

      // Link config
      linkConfig: this.formBuilder.group({
        url: ['', Validators.required],
        openInNewTab: [false],
      }),

      // Product config
      productConfig: this.formBuilder.group({
        categoryId: [''],
        openInNewTab: [false],
      }),
    });
  }

  private loadMenuOptions() {
    this.adminMenusService.apiAdminMenusOptionsGet().subscribe({
      next: (res) => {
        const options = res.data;
        this.menuTypes = options.menuTypes || [];
        this.singlePageOptions = options.singlePageOptions || [];
        this.menuOptions = options;
      },
      error: (error) => {
        console.error('載入選單選項失敗:', error);
        this.messageService.add({
          severity: 'error',
          summary: '錯誤',
          detail: '無法載入選單選項',
        });
      },
    });
  }

  private loadCategoryOptions() {
    this.categoryService.apiAdminCategoryGet().subscribe({
      next: (response) => {
        this.categoryOptions = response?.data || [];
      },
    });
  }

  private loadMenuForEdit() {
    if (!this.menuId) return;

    this.loading = true;

    this.adminMenusService.apiAdminMenusIdGet(this.menuId).subscribe({
      next: (response) => {
        // 根據 API 回應結構調整 - ApiAdminMenusPost201Response has data.menu structure
        const menu = response?.data;
        if (menu) {
          this.populateForm(menu);
        }
        this.loading = false;
      },
      error: (error) => {
        console.error('載入選單失敗:', error);
        this.messageService.add({
          severity: 'error',
          summary: '錯誤',
          detail: '無法載入選單資料',
        });
        this.loading = false;
        this.router.navigate(['/menus']);
      },
    });
  }

  private populateForm(menu: Menu) {
    this.menuForm.patchValue({
      name: menu.name || '',
      slug: menu.slug || '',
      menuType: menu.menuType || 'single',
      displayOrder: menu.displayOrder || 1,
      isActive: menu.isActive ?? true,
      parentId: menu.parentId || '',
      level: menu.level || 1,
      requiredRole: menu.requiredRole || 'public',
      icon: menu.icon || '',
      description: menu.description || '',
    });

    if (menu.menuType === 'category' && menu.categoryConfig) {
      this.menuForm.get('categoryConfig')?.patchValue(menu.categoryConfig);
    }

    if (menu.menuType === 'single' && menu.singleConfig) {
      this.menuForm.get('singleConfig')?.patchValue(menu.singleConfig);
    }

    if (menu.menuType === 'link' && menu.linkConfig) {
      this.menuForm.get('linkConfig')?.patchValue(menu.linkConfig);
    }

    if (menu.menuType === 'product' && menu.productConfig) {
      this.menuForm.get('productConfig')?.patchValue(menu.productConfig);
    }

    this.onMenuTypeChange(menu.menuType || 'single');
  }

  onMenuTypeChange(menuType: string) {
    // 根據選單類型顯示/隱藏相關配置
    const categoryConfig = this.menuForm.get('categoryConfig');
    const singleConfig = this.menuForm.get('singleConfig');
    const linkConfig = this.menuForm.get('linkConfig');
    const productConfig = this.menuForm.get('productConfig');

    // 先禁用所有配置
    categoryConfig?.disable();
    singleConfig?.disable();
    linkConfig?.disable();
    productConfig?.disable();

    // 根據選單類型啟用對應配置
    switch (menuType) {
      case 'category':
        categoryConfig?.enable();
        break;
      case 'single':
        singleConfig?.enable();
        break;
      case 'link':
        linkConfig?.enable();
        break;
      case 'product':
        productConfig?.enable();
        break;
    }
  }

  onSubmit() {
    if (this.menuForm.valid) {
      this.submitting = true;

      const formValue = this.menuForm.value;
      // 處理 slug 欄位 - 如果留空則根據 name 自動生成
      let slug = formValue.slug?.trim();
      if (!slug && formValue.name) {
        slug = this.generateSlug(formValue.name);
      }

      const menuInput: MenuInput = {
        name: formValue.name,
        slug: slug || undefined,
        menuType: formValue.menuType,
        displayOrder: formValue.displayOrder,
        isActive: formValue.isActive,
        parentId: formValue.parentId || undefined,
        level: formValue.level,
        requiredRole: formValue.requiredRole,
        icon: formValue.icon,
        description: formValue.description,
      };

      // 根據選單類型添加相應配置
      if (formValue.menuType === 'category') {
        const categoryConfig = {
          contentType: formValue.categoryConfig.contentType,
          displayStyle: formValue.categoryConfig.displayStyle,
          itemsPerPage: formValue.categoryConfig.itemsPerPage,
          sortBy: formValue.categoryConfig.sortBy,
          sortOrder: formValue.categoryConfig.sortOrder,
          categoryFilter: formValue.categoryConfig.categoryFilter || undefined,
          tagFilter:
            formValue.categoryConfig.tagFilter?.length > 0
              ? formValue.categoryConfig.tagFilter
              : undefined,
          enableSearch: formValue.categoryConfig.enableSearch,
          enableCategoryFilter: formValue.categoryConfig.enableCategoryFilter,
        };
        menuInput.categoryConfig = categoryConfig;
      } else if (formValue.menuType === 'single') {
        const singleConfig = {
          contentId: formValue.singleConfig.contentId || undefined,
          openInNewTab: formValue.singleConfig.openInNewTab,
        };
        menuInput.singleConfig = singleConfig;
      } else if (formValue.menuType === 'link') {
        const linkConfig = {
          url: formValue.linkConfig.url,
          openInNewTab: formValue.linkConfig.openInNewTab,
        };
        menuInput.linkConfig = linkConfig;
      } else if (formValue.menuType === 'product') {
        const productConfig = {
          categoryId: formValue.productConfig.categoryId || undefined,
          openInNewTab: formValue.productConfig.openInNewTab,
        };
        menuInput.productConfig = productConfig;
      }

      if (this.isEditMode && this.menuId) {
        this.updateMenu(this.menuId, menuInput);
      } else {
        this.createMenu(menuInput);
      }
    } else {
      this.markFormGroupTouched(this.menuForm);
      this.messageService.add({
        severity: 'error',
        summary: '錯誤',
        detail: '請填寫必填欄位並確認格式正確',
      });
    }
  }

  private createMenu(menuInput: MenuInput) {
    this.adminMenusService.apiAdminMenusPost(menuInput).subscribe({
      next: () => {
        this.messageService.add({
          severity: 'success',
          summary: '成功',
          detail: '選單已建立',
        });
        this.router.navigate(['/menus']);
      },
      error: (error) => {
        console.error('建立選單失敗:', error);
        this.messageService.add({
          severity: 'error',
          summary: '錯誤',
          detail: '建立選單失敗',
        });
      },
      complete: () => {
        this.submitting = false;
      },
    });
  }

  private updateMenu(id: string, menuInput: MenuInput) {
    this.adminMenusService.apiAdminMenusIdPut(id, menuInput).subscribe({
      next: () => {
        this.messageService.add({
          severity: 'success',
          summary: '成功',
          detail: '選單已更新',
        });
        this.router.navigate(['/menus']);
      },
      error: (error) => {
        console.error('更新選單失敗:', error);
        this.messageService.add({
          severity: 'error',
          summary: '錯誤',
          detail: '更新選單失敗',
        });
      },
      complete: () => {
        this.submitting = false;
      },
    });
  }

  onCancel() {
    this.router.navigate(['/menus']);
  }

  private markFormGroupTouched(formGroup: FormGroup) {
    Object.keys(formGroup.controls).forEach((key) => {
      const control = formGroup.controls[key];
      control.markAsTouched();

      if (control instanceof FormGroup) {
        this.markFormGroupTouched(control);
      }
    });
  }

  // Helper methods for template
  isFieldInvalid(fieldName: string): boolean {
    const field = this.menuForm.get(fieldName);
    return !!(field && field.invalid && (field.dirty || field.touched));
  }

  getFieldError(fieldName: string): string {
    const field = this.menuForm.get(fieldName);
    if (field && field.errors) {
      if (field.errors['required']) return '此欄位為必填';
      if (field.errors['maxlength'])
        return `最多 ${field.errors['maxlength'].requiredLength} 個字元`;
      if (field.errors['min']) return `最小值為 ${field.errors['min'].min}`;
      if (field.errors['max']) return `最大值為 ${field.errors['max'].max}`;
    }
    return '';
  }

  get categoryConfigForm(): FormGroup {
    return this.menuForm.get('categoryConfig') as FormGroup;
  }

  get singleConfigForm(): FormGroup {
    return this.menuForm.get('singleConfig') as FormGroup;
  }

  get linkConfigForm(): FormGroup {
    return this.menuForm.get('linkConfig') as FormGroup;
  }

  get productConfigForm(): FormGroup {
    return this.menuForm.get('productConfig') as FormGroup;
  }

  get isCategory(): boolean {
    return this.menuForm.get('menuType')?.value === 'category';
  }

  get isSingle(): boolean {
    return this.menuForm.get('menuType')?.value === 'single';
  }

  get isLink(): boolean {
    return this.menuForm.get('menuType')?.value === 'link';
  }

  get isProduct(): boolean {
    return this.menuForm.get('menuType')?.value === 'product';
  }
  private generateSlug(title: string): string {
    if (!title) return '';

    return (
      title
        .trim()
        .toLowerCase()
        // 移除特殊字符，保留中文、英文、數字、空格和連字符
        .replace(/[^\u4e00-\u9fa5a-zA-Z0-9\s-]/g, '')
        // 將多個空格轉換為單個連字符
        .replace(/\s+/g, '-')
        // 移除開頭和結尾的連字符
        .replace(/^-+|-+$/g, '')
        // 將多個連續的連字符轉換為單個
        .replace(/-+/g, '-')
    );
  }
}
