import { Component, OnInit } from '@angular/core';
import { Router } from '@angular/router';
import { MessageService, ConfirmationService } from 'primeng/api';
import { TreeNode, TreeDragDropService } from 'primeng/api';
import { AdminMenusService } from '../../../../../../libs/openapi/src/api/admin-menus.service';
import { Menu } from '../../../../../../libs/openapi/src/model/menu';
import { MenuWithChildren } from '../../../../../../libs/openapi/src/model/menu-with-children';
import { ApiAdminMenusTreeGet200Response } from '../../../../../../libs/openapi/src/model/api-admin-menus-tree-get200-response';
import { TreeNodeDropEvent } from 'primeng/tree';

@Component({
  selector: 'app-menu-list',
  templateUrl: './menu-list.component.html',
  styleUrls: ['./menu-list.component.scss'],
  providers: [MessageService, ConfirmationService, TreeDragDropService],
})
export class MenuListComponent implements OnInit {
  menuTree: TreeNode[] = [];
  loading = false;

  constructor(
    private adminMenusService: AdminMenusService,
    private confirmationService: ConfirmationService,
    private messageService: MessageService,
    private router: Router
  ) {}

  ngOnInit() {
    this.loadMenuTree();
  }

  loadMenuTree() {
    this.loading = true;

    this.adminMenusService.apiAdminMenusTreeGet().subscribe({
      next: (response: ApiAdminMenusTreeGet200Response) => {
        const menuTreeData = response?.data || [];
        this.menuTree = this.convertToTreeNodes(menuTreeData);
        this.loading = false;
      },
      error: (error) => {
        console.error('載入選單樹狀結構失敗:', error);
        this.messageService.add({
          severity: 'error',
          summary: '錯誤',
          detail: '無法載入選單',
        });
        this.loading = false;
        this.menuTree = [];
      },
    });
  }

  /** MenuWithChildren 轉成 tree 需要的格式，限制最多三層 */
  private convertToTreeNodes(
    menus: MenuWithChildren[],
    level: number = 0
  ): TreeNode[] {
    return menus.map((menu) => ({
      key: menu._id || '',
      label: menu.name,
      data: {
        ...menu,
        level: level,
        displayOrder: menu.displayOrder || 0,
      },
      children:
        menu.children && level < 2
          ? this.convertToTreeNodes(menu.children, level + 1)
          : [],
      expanded: true,
    }));
  }

  onNodeDrop(event: TreeNodeDropEvent) {
    // 驗證層級限制
    if (!this.validateNodeDropLevel(event)) {
      this.messageService.add({
        severity: 'warn',
        summary: '警告',
        detail: '選單層級不能超過三層',
      });
      // 重新載入樹狀結構以恢復原狀態
      this.loadMenuTree();
      return;
    }

    // 處理樹節點拖拽重排序
    const flatMenuOrders = this.convertTreeToFlatStructure(this.menuTree);
    this.adminMenusService
      .apiAdminMenusOrderPatch({ menuOrders: flatMenuOrders })
      .subscribe({
        next: () => {
          this.messageService.add({
            severity: 'info',
            summary: '提示',
            detail: '順序更新成功',
          });
          // 重新載入樹狀結構以獲取最新狀態
          this.loadMenuTree();
        },
        error: (error) => {
          console.error('更新選單順序失敗:', error);
          this.messageService.add({
            severity: 'error',
            summary: '錯誤',
            detail: '更新選單順序失敗',
          });
        },
      });
  }

  /**
   * 驗證拖拽後的節點是否符合層級限制（最多三層）
   * @param event 樹節點拖拽事件
   * @returns 是否通過驗證
   */
  private validateNodeDropLevel(event: TreeNodeDropEvent): boolean {
    const maxDepth = this.calculateTreeDepth(this.menuTree);
    return maxDepth <= 3;
  }

  /**
   * 計算樹的最大深度
   * @param nodes 樹節點陣列
   * @returns 最大深度
   */
  private calculateTreeDepth(nodes: TreeNode[]): number {
    if (!nodes || nodes.length === 0) {
      return 0;
    }

    let maxDepth = 1;
    for (const node of nodes) {
      if (node.children && node.children.length > 0) {
        const childDepth = this.calculateTreeDepth(node.children);
        maxDepth = Math.max(maxDepth, 1 + childDepth);
      }
    }

    return maxDepth;
  }

  /**
   * 將樹狀結構轉換成扁平的數據庫格式
   * @param nodes TreeNode 陣列
   * @param parentId 父節點 ID
   * @param level 層級
   * @returns 扁平化的選單順序陣列
   */
  private convertTreeToFlatStructure(
    nodes: TreeNode[],
    parentId: string | undefined = undefined,
    level: number = 0
  ): Array<{
    id: string;
    parentId?: string;
    level: number;
    displayOrder: number;
  }> {
    const result: Array<{
      id: string;
      parentId?: string;
      level: number;
      displayOrder: number;
    }> = [];

    nodes.forEach((node, index) => {
      // 添加當前節點
      result.push({
        id: node.key!,
        parentId: parentId,
        level: level,
        displayOrder: index,
      });

      // 遞歸處理子節點
      if (node.children && node.children.length > 0) {
        const childResults = this.convertTreeToFlatStructure(
          node.children,
          node.key!,
          level + 1
        );
        result.push(...childResults);
      }
    });

    return result;
  }

  editMenu(menu: Menu) {
    this.router.navigate(['/menus/edit', menu._id]);
  }

  confirmDelete(menu: Menu) {
    this.confirmationService.confirm({
      message: `確定要刪除選單「${menu.name}」嗎？`,
      header: '確認刪除',
      icon: 'pi pi-exclamation-triangle',
      accept: () => {
        this.deleteMenu(menu);
      },
    });
  }

  private deleteMenu(menu: Menu) {
    if (!menu._id) return;

    this.adminMenusService.apiAdminMenusIdDelete(menu._id).subscribe({
      next: () => {
        this.messageService.add({
          severity: 'success',
          summary: '成功',
          detail: '選單已刪除',
        });
        this.loadMenuTree();
      },
      error: (error) => {
        this.messageService.add({
          severity: 'error',
          summary: '錯誤',
          detail: '刪除選單失敗',
        });
      },
    });
  }

  getMenuTypeLabel(menuType: string): string {
    switch (menuType) {
      case 'category':
        return '內容目錄';
      case 'single':
        return '單頁';
      case 'link':
        return '連結';
      case 'product':
        return '產品';
      default:
        return menuType;
    }
  }

  getMenuTypeSeverity(
    menuType: string
  ): 'success' | 'info' | 'warning' | 'danger' {
    switch (menuType) {
      case 'category':
        return 'success';
      case 'single':
        return 'info';
      case 'link':
        return 'warning';
      default:
        return 'info';
    }
  }
}
